import{f as s,o as t,c as r,aq as a}from"./chunks/framework.CAfuRaXs.js";const m=JSON.parse('{"title":"Tools & Frameworks","description":"","frontmatter":{},"headers":[],"relativePath":"technik/ecosystem/toolsAndFrameworks.md","filePath":"technik/ecosystem/toolsAndFrameworks.md"}'),i={name:"technik/ecosystem/toolsAndFrameworks.md"};function l(n,e,o,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="tools-frameworks" tabindex="-1">Tools &amp; Frameworks <a class="header-anchor" href="#tools-frameworks" aria-label="Permalink to &quot;Tools &amp; Frameworks&quot;">​</a></h1><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><ul><li>Github <ul><li>Sourcecodeverwaltung</li><li>Continuous Integration</li><li>Imageregistry</li></ul></li><li>Zenhub <ul><li>Projektmanagement</li></ul></li><li><s>Docker</s> (deprecated) -&gt; Podman</li><li>SoapUI <ul><li>Beispielrequests</li></ul></li></ul><h3 id="zenhub" tabindex="-1">Zenhub <a class="header-anchor" href="#zenhub" aria-label="Permalink to &quot;Zenhub&quot;">​</a></h3><p>Mit Zenhub organisieren wir unsere Entwicklung. Es basiert auf den GitHub-Issues. Die Pipelines von Zenhub unterstützen unseren Entwicklungsprozess nach Scrum hervorragend. Um diesen Prozess auch in GitHub leichter sichtbar zu machen, verwenden wir Labels. Diese werden automatisch beim Verschieben eines Issues von einer Pipeline zur nächsten aktualisiert.</p><p>Alle Labels, die darstellen, in welchem Schritt des Entwicklungsprozesses sich das Issue befindet, beginnen mit <a href="https://github.com/it-at-m/Wahllokalsystem/labels?q=step" target="_blank" rel="noreferrer"><code>step_</code>-Label</a>.</p><div class="caution custom-block github-alert"><p class="custom-block-title">Manuelle Synchronisierung der Labels bei der Zenhub-Automatisierung erforderlich</p><p>Automatisierungsregeln in Zenhub, die mit Labels arbeiten, müssen von Hand angepasst werden, wenn der Name eines Labels geändert wird.</p></div><p>Noch nicht eingeordnete Issues haben kein <code>step_</code>-Label. Im Laufe der Entwicklung durchlaufen die Issues folgende Schritte:</p><ul><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_po-review" target="_blank" rel="noreferrer"><code>step_po-review</code></a> ... Das Issue wartet auf die Abnahme durch den Product Owner.</li><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_refinement" target="_blank" rel="noreferrer"><code>step_refinement</code></a> ... Die fachlichen Anforderungen sind definiert und bereit, vom Entwicklungsteam abgenommen zu werden.</li><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_product-backlog" target="_blank" rel="noreferrer"><code>step_product-backlog</code></a> ... Das Issue ist für die Umsetzung vorgesehen.</li><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_sprint-backlog" target="_blank" rel="noreferrer"><code>step_sprint-backlog</code></a> ... Das Issue ist zur Umsetzung im aktuellen Sprint vorgesehen.</li><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_in-progress" target="_blank" rel="noreferrer"><code>step_in-progress</code></a> ... Das Issue wird von einer Person (siehe Assignee) aus dem Entwicklungsteam umgesetzt.</li><li><a href="https://github.com/it-at-m/Wahllokalsystem/issues?q=state%3Aopen%20label%3Astep_code-review" target="_blank" rel="noreferrer"><code>step_code-review</code></a> ... Die Implementierung des Issues ist abgeschlossen und es erfolgt aktuell ein Code Review.</li></ul><p>Ist ein Issue umgesetzt, wird es geschlossen und hat wieder kein <code>step_</code>-Label.</p><h2 id="frameworks" tabindex="-1">Frameworks <a class="header-anchor" href="#frameworks" aria-label="Permalink to &quot;Frameworks&quot;">​</a></h2><ul><li>Spring-Boot</li><li>Vue.js</li><li>Vuetify</li><li>VitePress</li></ul>',12)])])}const p=s(i,[["render",l]]);export{m as __pageData,p as default};
